{"content": "1|// The multiplayer message language: one entry per message type, declaring its
2|// direction ('cs' client → server, 'sc' server → client), its wire fields and
3|// its design rate. One shared encode/decode pair is driven by those entries,
4|// so every packet is validated against the same definitions that produce the
5|// protocol table in NOTES.md (`node tools/protocol-table.mjs`).
6|//
7|// Wire format: JSON text frames tagged with `type` — messages are tiny and the
8|// intranet is fast, so readable beats compact. All times are milliseconds in
9|// the shared server clock (clients learn their offset via ping/pong, because
10|// the browser's WebSocket API hides the protocol-level ping/pong from JS).
11|
12|export const STAGES = ['lobby', 'countdown', 'racing', 'finished', 'ceremony'];
13|export const MAX_PLAYERS = 4;
14|
15|const err = (where, why) => new Error(`protocol: ${where} ${why}`);
16|
17|// --- Field validators (used by encode AND decode, so both sides agree) ---
18|
19|function str(v, w) {
20|  if (typeof v !== 'string' || v.length < 1 || v.length > 24) throw err(w, 'must be a 1..24 char string');
21|  return v;
22|}
23|function num(v, w) {
24|  if (typeof v !== 'number' || !Number.isFinite(v)) throw err(w, 'must be a finite number');
25|  return v;
26|}
27|function idNum(v, w) {
28|  if (!Number.isInteger(v) || v < 1) throw err(w, 'must be a positive integer');
29|  return v;
30|}
31|function seedNum(v, w) {
32|  if (!Number.isInteger(v) || v < 0) throw err(w, 'must be a non-negative integer');
33|  return v;
34|}
35|function stageOf(v, w) {
36|  if (!STAGES.includes(v)) throw err(w, `must be one of ${STAGES.join('|')}`);
37|  return v;
38|}
39|function rosterOf(v, w) {
40|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
41|  return v.map((p, i) => {
42|    if (typeof p !== 'object' || p === null || Array.isArray(p)) throw err(`${w}[${i}]`, 'must be an object');
43|    for (const k of Object.keys(p)) if (k !== 'id' && k !== 'name') throw err(`${w}[${i}]`, `has unknown field ${k}`);
44|    if (!('id' in p) || !('name' in p)) throw err(`${w}[${i}]`, 'needs id and name');
45|    return { id: idNum(p.id, `${w}[${i}].id`), name: str(p.name, `${w}[${i}].name`) };
46|  });
47|}
48|
49|const tOrNull = (v, w) => (v === null ? null : num(v, w));
50|const boolOf = (v, w) => {
51|  if (typeof v !== 'boolean') throw err(w, 'must be a boolean');
52|  return v;
53|};
54|// One results-table row for the settled race: finished players first in
55|// official order (time, then earliest report), DNFs last with t = null.
56|const resultsOf = (v, w) => {
57|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
58|  return v.map((r, i) => {
59|    if (typeof r !== 'object' || r === null || Array.isArray(r)) throw err(`${w}[${i}]`, 'must be an object');
60|    for (const k of Object.keys(r)) if (k !== 'id' && k !== 'name' && k !== 't' && k !== 'dnf') throw err(`${w}[${i}]`, `has unknown field ${k}`);
61|    if (!('id' in r) || !('name' in r) || !('t' in r) || !('dnf' in r)) throw err(`${w}[${i}]`, 'needs id, name, t and dnf');
62|    return {
63|      id: idNum(r.id, `${w}[${i}].id`),
64|      name: str(r.name, `${w}[${i}].name`),
65|      t: tOrNull(r.t, `${w}[${i}].t`),
66|      dnf: boolOf(r.dnf, `${w}[${i}].dnf`),
67|    };
68|  });
69|};
70|
71|// --- The registry ---
72|
73|export const MESSAGES = {
74|  // client → server
75|  join:       { dir: 'cs', rate: 'once, on entering the lobby', fields: { name: str } },
76|  name:       { dir: 'cs', rate: 'on change, in lobby',          fields: { name: str } },
77|  start:      { dir: 'cs', rate: 'user-triggered',               fields: {} },
78|  pos:        { dir: 'cs', rate: '15 Hz while racing',           fields: { x: num, z: num, h: num, s: num } },
79|  finish:     { dir: 'cs', rate: 'once per race',                fields: { t: num } },
80|  ping:       { dir: 'cs', rate: 'about 1 Hz while syncing',     fields: { t: num } },
81|  // server → client
82|  roster:     { dir: 'sc', rate: 'on change',                    fields: { players: rosterOf, seed: seedNum } },
83|  countdown:  { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
84|  go:         { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
85|  posRelay:   { dir: 'sc', rate: 'per player, 15 Hz',            fields: { id: idNum, x: num, z: num, h: num, s: num } },
86|  stage:      { dir: 'sc', rate: 'on change',                    fields: { stage: stageOf } },
87|  disconnect: { dir: 'sc', rate: 'on player leaving',            fields: { id: idNum } },
88|  pong:       { dir: 'sc', rate: 'on ping',                      fields: { t: num, s: num } },
89|  finishInfo: { dir: 'sc', rate: 'per finisher, once',           fields: { id: idNum, t: num } },
90|  results:    { dir: 'sc', rate: 'once, when the race is settled', fields: { players: resultsOf } },
91|};
92|
93|// --- The encode/decode pair ---
94|
95|// encode(type, data) → JSON string, fields validated on the way out.
96|export function encode(type, data) {
97|  const def = MESSAGES[type];
98|  if (!def) throw err(type, 'is not a known message type');
99|  const out = { type };
100|  for (const [f, check] of Object.entries(def.fields)) out[f] = check(data?.[f], `${type}.${f}`);
101|  return JSON.stringify(out);
102|}
103|
104|// decode(text) → { type, data }, or throws on anything unknown or malformed:
105|// bad JSON, non-objects, unknown types, missing/unknown fields, wrong value types.
106|export function decode(text) {
107|  let m = null;
108|  try { m = JSON.parse(text); } catch { /* handled below */ }
109|  if (typeof m !== 'object' || m === null || Array.isArray(m)) throw err('packet', 'must be a JSON object');
110|  const def = MESSAGES[m.type];
111|  if (!def) throw err('packet', `unknown message type ${JSON.stringify(m.type)}`);
112|  const known = Object.keys(def.fields);
113|  for (const k of Object.keys(m)) if (k !== 'type' && !known.includes(k)) throw err(m.type, `unknown field ${k}`);
114|  const data = {};
115|  for (const [f, check] of Object.entries(def.fields)) data[f] = check(m[f], `${m.type}.${f}`);
116|  return { type: m.type, data };
117|}
118|
119|// Markdown table of the whole protocol, generated from the registry. NOTES.md
120|// embeds it between markers; a test keeps the two from drifting apart.
121|export function protocolTable() {
122|  const rows = Object.entries(MESSAGES).map(([name, d]) =>
123|    `| ${name} | ${d.dir === 'cs' ? 'client → server' : 'server → client'} | ${Object.keys(d.fields).join(' ') || '—'} | ${d.rate} |`);
124|  return ['| type | from | fields | rate |', '|---|---|---|---|', ...rows].join('\n');
125|}", "total_lines": 125, "file_size": 6448, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// Phase 2: every rule of the race, driven END-TO-END through fakeNet pairs —
2|// joins → start → positions → finishes → results → ceremony, no real socket.
3|import { test } from 'node:test';
4|import assert from 'node:assert/strict';
5|import { FakeNet, FakeServer } from '../server/fakeNet.js';
6|import { createRaceState, CLOSE_FULL, CLOSE_STARTED } from '../server/raceState.js';
7|import { decode, encode } from '../server/protocol.js';
8|
9|// A wired-up server + client handles on the virtual network. Each client
10|// records every message it is sent as {type, data}; `client.send(type, data)`
11|// encodes + delivers with the client's injected latency.
12|function world({ latency = 0 } = {}) {
13|  const net = new FakeNet();
14|  const server = new FakeServer(net);
15|  const rejected = []; // every { code, reason } the server turned someone away with
16|  const race = createRaceState({
17|    seed: 42,
18|    now: () => net.now,
19|    send: (conn, type, data) => conn.send(encode(type, data)),
20|    close: (conn, code, reason) => {
21|      rejected.push({ code, reason }); // visible even though the reject fires before any client handler exists
22|      conn.close(code, reason);
23|    },
24|    schedule: (delayMs, fn) => net.schedule(delayMs, fn),
25|  });
26|  server.onConnect = (conn) => {
27|    race.connect(conn);
28|    conn.onMessage = (text) => race.onMessage(conn, text);
29|    conn.onClose = () => race.disconnect(conn);
30|  };
31|  const client = (opts) => {
32|    const conn = server.connect({ latency });
33|    const me = { conn, messages: [], id: null, closedWith: null };
34|    conn.onMessage = (text) => {
35|      const m = decode(text);
36|      me.messages.push(m);
37|      if (m.type === 'roster') me.id = m.data.players.find((p) => p.name === me.name)?.id ?? me.id;
38|    };
39|    conn.onClose = () => { me.closedWith = conn.closedWith; };
40|    me.name = null;
41|    me.join = (name) => {
42|      me.name = name;
43|      conn.send(encode('join', { name }));
44|      return me;
45|    };
46|    me.send = (type, data) => conn.send(encode(type, data));
47|    me.saw = (type) => me.messages.filter((m) => m.type === type);
48|    return me;
49|  };
50|  return { net, race, client, rejected };
51|}
52|
53|test('start is rejected with fewer than 2 players', () => {
54|  const { race, client } = world();
55|  const a = client().join('A');
56|  a.send('start');
57|  assert.equal(race.stage, 'lobby');
58|  assert.deepEqual(a.saw('countdown'), []);
59|});
60|
61|test('the 5th connection is turned away, the 4 play', () => {
62|  const { race, client, net, rejected } = world();
63|  const four = ['A', 'B', 'C', 'D'].map((n) => client().join(n));
64|  net.advance(0);
65|  assert.equal(race.stage, 'lobby');
66|  client();
67|  net.advance(0);
68|  assert.deepEqual(rejected, [{ code: CLOSE_FULL, reason: 'lobby full' }]);
69|  assert.ok(four.every((c) => c.saw('roster').at(-1).data.players.length === 4), 'roster has four players');
70|});
71|
72|test('start gate opens with 2: lobby → countdown → go with one shared goAt', () => {
73|  const { race, client, net } = world();
74|  const [a, b] = [client().join('A'), client().join('B')];
75|  net.advance(0);
76|  a.send('start');
77|  assert.equal(race.stage, 'countdown');
78|  const countdown = a.saw('countdown');
79|  assert.equal(countdown.length, 1);
80|  assert.ok(Number.isFinite(countdown[0].data.goAt));
81|  net.advance(3000);
82|  assert.equal(race.stage, 'racing');
83|  for (const c of [a, b]) {
84|    assert.deepEqual(c.saw('go')[0].data, { goAt: countdown[0].data.goAt });
85|    assert.ok(c.saw('stage').some((m) => m.data.stage === 'racing'));
86|  }
87|});
88|
89|test('positions relay to everyone but the sender, only while the race runs', () => {
90|  const { client, net } = world();
91|  const [a, b, c] = [client().join('A'), client().join('B'), client().join('C')];
92|  net.advance(0);
93|  a.send('start');
94|  a.send('pos', { x: 1, z: 2, h: 0, s: 0 }); // during countdown: relayed (pre-green sanity), stage gate allows
95|  net.advance(0);
96|  assert.ok(b.saw('posRelay').some((m) => m.data.id === a.id && m.data.x === 1));
97|  net.advance(3000);
98|  b.send('pos', { x: 5, z: 6, h: 1, s: 3 });
99|  c.send('pos', { x: 7, z: 8, h: 1, s: 2 });
100|  net.advance(0);
101|  const got = a.saw('posRelay');
102|  assert.equal(got.filter((m) => m.data.id === a.id).length, 0, 'sender never receives own relay');
103|  assert.ok(got.some((m) => m.data.id === b.id && m.data.z === 6), 'b reaches a');
104|  assert.ok(got.some((m) => m.data.id === c.id && m.data.z === 8), 'c reaches a');
105|  assert.ok(!b.saw('posRelay').some((m) => m.data.id === b.id), 'b does not receive own relay');
106|  // After the results are settled, positions still relay, but in the lobby,
107|  // never: check stage gate by rewinding — fresh world instead.
108|  const fresh = world();
109|  const [x, y] = [fresh.client().join('X'), fresh.client().join('Y')];
110|  fresh.net.advance(0);
111|  x.send('pos', { x: 1, z: 2, h: 0, s: 0 });
112|  fresh.net.advance(0);
113|  assert.deepEqual(y.saw('posRelay'), [], 'no position relay in the lobby');
114|});
115|
116|test('finish order equals time order; a tie goes to the earliest report', () => {
117|  const { race, client, net } = world();
118|  const [a, b, c] = [client().join('A'), client().join('B'), client().join('C')];
119|  net.advance(0);
120|  a.send('start');
121|  net.advance(3000);
122|  c.send('finish', { t: 5000 }); // reports first, but the slowest time
123|  b.send('finish', { t: 4000 });
124|  a.send('finish', { t: 4000 }); // equal times: b wins the tie by report order
125|  assert.equal(race.stage, 'finished', 'everyone home → results immediately');
126|  const results = a.saw('results')[0].data.players;
127|  assert.deepEqual(results.map((p) => ({ name: p.name, t: p.t, dnf: p.dnf })), [
128|    { name: 'B', t: 4000, dnf: false },
129|    { name: 'A', t: 4000, dnf: false },
130|    { name: 'C', t: 5000, dnf: false },
131|  ]);
132|  // Deterministic: an identical report sequence on a fresh world.
133|  const again = world();
134|  const [a2, b2] = [again.client().join('A'), again.client().join('B')];
135|  again.net.advance(0);
136|  a2.send('start');
137|  again.net.advance(3000);
138|  b2.send('finish', { t: 1000 });
139|  a2.send('finish', { t: 1000 });
140|  const r2 = a2.saw('results')[0].data.players;
141|  assert.deepEqual(r2.map((p) => p.name), ['B', 'A']);
142|});
143|
144|test('DNF: disconnect mid-race never blocks the ceremony', () => {
145|  const { race, client, net } = world();
146|  const [a, b, c] = [client().join('A'), client().join('B'), client().join('C')];
147|  net.advance(0);
148|  a.send('start');
149|  net.advance(3000);
150|  c.conn.close(); // C drops out mid-race
151|  net.advance(0);
152|  assert.ok(a.saw('disconnect').some((m) => m.data.id === c.id));
153|  a.send('finish', { t: 6000 });
154|  b.send('finish', { t: 7000 });
155|  net.advance(0);
156|  assert.equal(race.stage, 'finished', 'A + B home, C is DNF → settle at once');
157|  net.advance(2000);
158|  assert.equal(race.stage, 'ceremony');
159|  const results = a.saw('results')[0].data.players;
